\begin{equation}
    \min_{x\in \Gamma} F(x)=\sum_{i=1}^{m} g_i(x),  \label{pro}
\end{equation}

where $g_i(x)$'s are smooth and convex functions, and $\Gamma$ is a closed convex set. When $m$ is large, computing the exact gradient of $\sum_{i=1}^{m} g_i(x)$ becomes costly, and it gives rise to the so-called stochastic gradient descent (SGD) method, which only computes a single gradient at random or a mini-batch of randomly selected gradients at each iteration. However, SGD converges with a sublinear rate of $1/\epsilon$ even if all the functions $g_i(\cdot)$'s are strongly convex and smooth.


In this paper, we shall use the terminology of {\it gradient complexity}\/ to refer to the amount of times that the gradients
of functions $g_i$'s need be computed before reaching an $\epsilon$ optimal solution.


a function $g$ is called $\mu$-strongly convex if
\begin{equation}
    g(y)\geq g(x)+\left\langle\nabla g(x),y-x\right\rangle+\frac{\mu}{2}\|y-x\|^2, \quad \forall x,y\in \mathcal{X}
\end{equation}

and
%\begin{definition}
a function $g$ is called $L$-Lipschitz smooth if
\begin{equation}
    \|\nabla g(x)-\nabla g(y)\|\leq L\|x-y\|, \quad \forall x,y\in \mathcal{X} .
\end{equation}

\begin{assumption}
In Model~\eqref{pro}, $g_i(x)$ is assumed to be $L_i$-smooth and $\mu_i$-strongly convex, $i=1,2,...,m$.
%{\color{red} Define $\kappa_i= L_i /(m\mu)+1$ as the condition number for the $i$-th component, $i=1,2,...,m$. (This may be hard to sell! Let us change the model to simply assuming $g_i$ to be $L_i$-gradient smooth and $\mu_i$-strongly convex, and there is no $h$, and there is a constraint $x\in \Gamma$.) }
\end{assumption}

Recall the problem
\[
F(x)=\sum_{i=1}^m g_i(x)=\sum_{i=1}^m \hat{g}_i(x)+h(x),
\]

where we let $\hat{g}_i(x) := g_i(x)-\frac{\mu_i}{2}\|x\|^2$, $h(x) := \frac{\mu}{2}\|x\|^2$, where $\mu=\sum_{i=1}^m \mu_i$.
We use the following estimation of the gradient of the first term,
\[
\widetilde{\nabla}^{k}=\frac{1}{\pi_{i_{k}}}\left(\nabla \hat{g}_{i_k}(y_{i_k}^k)-\nabla \hat{g}_{i_k}(\phi_{i_k}^k)\right)+  \sum_{i=1}^m\nabla \hat{g}_{i}(\phi_{i}^k){\color{red},}
\]

where $i_k$ is sampled from $\{1,2,\cdots,m\}$ with the probability
\[
\pi_i=\frac{\sqrt{L_i}}{2\sum_{j=1}^m\sqrt{L_j}}+\frac{1}{2m},\,\, i=1,2,...,m.
\]

Observe the gradient estimator $\widetilde{\nabla}^{k}$ is biased with expectation $\sum_{i=1}^m\nabla \hat{g}_{i}(y_{i}^k)$, if we extend the definition to all $y_{i}^{k}:=\tau_{i} x^{k}+(1-\tau_{i}) \phi_{i}^{k}$.


\begin{algorithm}[h]
\caption{Generalized SSNM }
\label{Algorithm1}
\begin{algorithmic}
\STATE{$\phi_1=\phi_2=\cdots=\phi_m=x^1$}
\STATE{$\pi_i=\frac{\sqrt{L_i}}{2\sum_{j=1}^m\sqrt{L_j}}+\frac{1}{2m}$}
\STATE{$\tau_i=\lambda/\pi_i$}
\FOR{$k=1,2,..., K$}
\STATE{Sample $i_k$ from $\{1,2,\cdots,m\}$ with probability $\{\pi_i\}_{i=1}^{m}$}
\STATE{$y_{i_{k}}^{k}=\tau_{i_{k}} x^{k}+(1-\tau_{i_{k}}) \phi_{i_{k}}^{k}$}
\STATE{$\widetilde{\nabla}^{k}=\frac{1}{\pi_{i_{k}}}\left(\nabla \hat{g}_{i_k}(y_{i_k}^k)-\nabla \hat{g}_{i_k}(\phi_{i_k}^k)\right)+  \sum_{i=1}^m\nabla \hat{g}_{i}(\phi_{i}^k)$}
\STATE{Perform a proximal/projection step\\ $x^{k+1}=\arg \min _{x\in \Gamma}\left\{h(x)+\left\langle\widetilde{\nabla}^{k}, x\right\rangle+\frac{1}{2 \eta}\left\|x^{k}-x\right\|^{2}\right\}$}
\STATE{Sample $j_k$ from $\{1,2,\cdots,m\}$ with probability $\{\pi_i\}_{i=1}^{m}$}
\STATE{$\phi_{j_{k}}^{k+1}=\tau_{j_{k}} x^{k+1}+(1-\tau_{j_{k}}) \phi_{j_{k}}^{k}$}
\ENDFOR
\STATE \textbf{return} $x^{k+1}$ 
\end{algorithmic}
\end{algorithm}

