    &=& \mathbb{E}_{i_{k}}\left[\left\|\frac{1}{\pi_{i_{k}}}\left(\nabla \hat{g}_{i_{k}}\left(y_{i_{k}}^{k}\right)-\nabla \hat{g}_{i_{k}}\left(\phi_{i_{k}}^{k}\right)\right)- \sum_{i=1}^{m}\left(\nabla \hat{g}_{i}\left(y_{i}^{k}\right)-\nabla \hat{g}_{i}\left(\phi_{i}^{k}\right)\right) \right\|^{2}\right] \\
    & \overset{\eqref{ex-ineq}}{\leq} & \mathbb{E}_{i_{k}}\left[\left\|\frac{1}{\pi_{i_{k}}}\left(\nabla \hat{g}_{i_{k}}\left(y_{i_{k}}^{k}\right)-\nabla \hat{g}_{i_{k}}\left(\phi_{i_{k}}^{k}\right)\right) \right\|^{2}\right] \\ %\label{ineq1}\\
