\[
x^{k+1} := \arg \min _{x\in \Gamma}\left\{h(x)+\left\langle\widetilde{\nabla}^{k}, x\right\rangle+\frac{1}{2 \eta}\left\|x^{k}-x\right\|^{2}\right\}.
\]
Then, for all $u\in \Gamma$, it holds that
\begin{eqnarray*}
& & \left\langle\widetilde{\nabla}^{k}, x^{k+1}-u\right\rangle \\
& \leq & -\frac{1}{2 \eta}\left\|x^{k+1}-x^{k}\right\|^{2}+\frac{1}{2 \eta}\left\|x^{k}-u\right\|^{2}-\frac{1+\eta \mu}{2 \eta}\left\|x^{k+1}-u\right\|^{2}+h(u)-h\left(x^{k+1}\right).
\end{eqnarray*}
\end{lemma}

