    &\leq & \sum_{i=1}^{m} \frac{1-\tau_{i}}{\tau_{i}} \hat{g}_{i}\left(\phi_{i}^{k}\right)+\frac{1}{2 \eta}\left\|x^{k}-x^{\star}\right\|^{2}-\frac{1+\eta \mu}{2 \eta} \mathbb{E}_{i_{k}}\left[\left\|x^{k+1}-x^{\star}\right\|^{2}\right]-\mathbb{E}_{i_{k}}\left[h\left(x^{k+1}\right)\right].
\end{eqnarray*}

Applying the above inequality and using $F_{i}(\cdot):=\hat{g}_{i}(\cdot)+\frac 1 m h(\cdot)$, we further derive
\begin{eqnarray*}
    &      &  \mathbb{E}_{i_{k},j_{k}}\left[\frac{1}{\pi_{j_{k}}\tau_{j_{k}}}F_{j_{k}}\left(\phi_{j_{k}}^{k+1}\right)\right]-F(x^{\star})\\
    &\leq  & \sum_{i=1}^{m} \frac{1-\tau_{i}}{\tau_{i}} F_{i}\left(\phi_{i}^{k}\right)+\frac{1}{2 \eta}\left\|x^{k}-x^{\star}\right\|^{2}-\frac{1+\eta \mu}{2 \eta} \mathbb{E}_{i_{k}}\left[\left\|x^{k+1}-x^{\star}\right\|^{2}\right] .
\end{eqnarray*}

Adding $\mathbb{E}_{i_{k},j_{k}}\left[\sum_{i\neq j_k}\frac{1}{\pi_i\tau_i}F_i\left(\phi_i^{k}\right)\right]$ to both sides, we have
\begin{eqnarray*}
    &     & \mathbb{E}_{i_{k},j_{k}}\left[\sum_{i=1}^m\frac{1}{\pi_i\tau_i}\left(F_i\left(\phi_i^{k+1}\right)-F_i(x^{\star})\right)\right]\\
    &\leq & \sum_{i=1}^{m} \frac{1-\pi_i\tau_{i}}{\pi_i\tau_{i}} \left(F_{i}\left(\phi_{i}^{k}\right)-F_i(x^{\star})\right)+\frac{1}{2 \eta}\left\|x^{k}-x^{\star}\right\|^{2}-\frac{1+\eta \mu}{2 \eta} \mathbb{E}_{i_{k}} \left[\left\|x^{k+1}-x^{\star}\right\|^{2} \right] .
\end{eqnarray*}

Noticing $\sum_{i=1}^{m} \left(F_{i}\left(\phi_{i}^{k}\right)-F_i(x^{\star})\right)$ may not be positive, we need to add the following term in our Lyapunov function
\begin{eqnarray*}
  & &    -\sum_{i=1}^{m}\frac{1}{\pi_i\tau_i}\left\langle\nabla F_{i}\left(x^{\star}\right), \phi_{i}^{k+1}-x^{\star}\right\rangle \\
  &=&  -\frac{1}{\pi_{j_{k}} \tau_{j_{k}}}\left\langle\nabla F_{j_{k}}\left(x^{\star}\right), \phi_{j_{k}}^{k+1}-x^{\star}\right\rangle-
  \sum_{i \neq j_k } %I \atop \mathfrak{l}}^{m}
  \frac{1}{\pi_i\tau_i}\left\langle\nabla F_{i}\left(x^{\star}\right), \phi_{i}^{k}-x^{\star}\right\rangle\\
  &=& -\frac{1}{\pi_{j_{k}}}\left\langle\nabla F_{j_{k}}\left(x^{\star}\right), x^{k+1}-x^{\star}\right\rangle
    +\frac{1}{\pi_{j_{k}}}\left\langle\nabla F_{j_{k}}\left(x^{\star}\right), \phi_{j_{k}}^{k}-x^{\star}\right\rangle\\
  &  & - \sum_{i =1}^{m}\frac{1}{\pi_i\tau_i}\left\langle\nabla F_{i}\left(x^{\star}\right), \phi_{i}^{k}-x^{\star}\right\rangle .
\end{eqnarray*}

Telescoping the above inequalities, we have
%\begin{equation}
\begin{eqnarray*}
& & \mathbb{E}\left[\left\|x^{K+1}-x^{\star}\right\|^{2}\right] \\
&\leq& \left(1+\frac{\sqrt{\mu}}{4\sum_{j=1}^m\sqrt{L_j}}\right)^{-K} \cdot\left(\frac{2\eta}{\lambda(1+\eta \mu)}\left(F\left(x^{1}\right)-F\left(x^{\star}\right)\right)+\left\|x^{1}-x^{\star}\right\|^{2}\right) .
\end{eqnarray*}

Taking expectations and telescoping the above inequalities, we have
\begin{equation}
\mathbb{E}\left[\left\|x^{K+1}-x^{\star}\right\|^{2}\right] \leq\left(1+\frac{1}{4m}\right)^{-K} \cdot\left(\frac{2\eta}{\lambda(1+\eta \mu)}\left(F\left(x^{1}\right)-F\left(x^{\star}\right)\right)+\left\|x^{1}-x^{\star}\right\|^{2}\right) .
\end{equation}
Summarizing Case I and Case II, the theorem is proven.
